// === Tab: mySketch ===
const S = 150;
const NUM = 15;
let numX, numY;
let tiles;

function setup() {
	var numX = ~~(windowWidth/S),
			numY = ~~(windowHeight/S);
	createCanvas(numX*S, numY*S);
	background("beige");

	// noFill()
	noStroke();
	blendMode(DIFFERENCE)
	fill("yellow")
	strokeWeight(2)
	rectMode(CENTER)
	d = max(width, height) * 0.95

	tiles = [];
	for (let y = 1; y < numY; y++) {
		for (let x = 1; x < numX; x++) {
			tiles.push(new Tile(S * x, S * y, S * 0.85, S / NUM))
		}		
	}
}

function draw() {
	if (frameCount >= NUM) thisIsTheEnd();

	for (let t of tiles) {
		t.update()
		// stroke(random(32), random(32), random(64, 192))
		t.show()
	}
}

function thisIsTheEnd() {
	// noLoop() removed for animation

	blendMode(BLEND);
	noStroke()
	fill("white")
	const S4 = ~~(S/4);
	rectMode(CORNER)
	rect(0, 0, width, S4)
	rect(0, height-S4, width, S4)
	rect(0, 0, S4, height)
	rect(width - S4, 0, S4, height)
}

class Tile {
	constructor(x, y, s, d) {
		this.x = x; // pos
		this.y = y;
		this.s = s; // size
		this.d = d; // delta size
	}

	update() {
		this.s -= random(this.d, this.d * 1.5)
	}

	show() {
		if (this.s < 1) return;

		push()
		translate(this.x, this.y);
		rotate(random(-0.1, 0.1))
		const x = random(-this.d, this.d)
		const y = random(-this.d, this.d)
		rect(x, y, this.s)
		pop();
	}
}
